<?php require 'config.php';require_login();$uid=$_SESSION['user_id'];$q=$pdo->prepare('SELECT name,email,department,graduation_year,skills,resume FROM users WHERE id=?');$q->execute([$uid]);$user=$q->fetch();$q=$pdo->prepare('SELECT a.id,a.status,a.applied_at,j.title,j.company FROM applications a JOIN jobs j ON j.id=a.job_id WHERE a.user_id=? ORDER BY a.applied_at DESC');$q->execute([$uid]);$apps=$q->fetchAll();include 'header.php';?>
<h2>Welcome, <?=h($user['name'])?>!</h2><?php if(isset($_GET['applied'])):?><div class="alert alert-success">Application submitted (if not already applied).</div><?php endif;?>
<div class="row g-3 my-2"><div class="col-md-4"><div class="card p-3"><div class="text-secondary">Applications</div><div class="stat"><?=count($apps)?></div></div></div><div class="col-md-8"><div class="card p-3"><h5>My Profile</h5><p class="mb-1"><?=h($user['email'])?> · <?=h($user['department'])?></p><p class="mb-1">Graduation: <?=h($user['graduation_year'])?></p><p class="mb-0">Skills: <?=h($user['skills'])?></p><a class="btn btn-sm btn-outline-primary mt-3 align-self-start" href="profile.php">Edit profile / upload resume</a></div></div></div>
<h4 class="mt-4">Application Tracker</h4><div class="card p-3"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Role</th><th>Company</th><th>Applied</th><th>Status</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><?=h($a['title'])?></td><td><?=h($a['company'])?></td><td><?=h($a['applied_at'])?></td><td><span class="badge text-bg-info"><?=h($a['status'])?></span></td></tr><?php endforeach;?></tbody></table></div><?php if(!$apps):?><p class="text-secondary mb-0">You have not applied to any jobs yet.</p><?php endif;?></div><?php include 'footer.php';?>